    if not m:
        return []

    row_lengths = [len(row) for row in m]

    if len(set(row_lengths)) != 1:
        raise ValueError('Linhas de diferentes tamanhos')

    transposed_matrix = [[m[j][i] for j in range(len(m))] for i in range(len(m[0]))]

